    void cupomMenos50AbaixoDoMinimoRetornaCupomNaoAplicavel() throws Exception {
        String body = """
                {
                    "itens": [
                        {"nome": "Produto barato", "precoUnitario": 50.00, "quantidade": 1, "pesoKg": 0.5}
                    ],
                    "modalidadeEntrega": "RETIRADA_LOJA",
